#include <iostream>

class Rational {
private:
    int numerator;
    int denominator;
public:
    Rational(int n = 0, int d = 1) : numerator(n), denominator(d) {}
    int getNumerator() const { return numerator; }
    int getDenominator() const { return denominator; }
};

// Nonmember operator+
Rational operator+(const Rational& r1, const Rational& r2) {
    int num = r1.getNumerator() * r2.getDenominator() + r2.getNumerator() * r1.getDenominator();
    int den = r1.getDenominator() * r2.getDenominator();
    return Rational(num, den);
}

int main() {
    Rational r1(2, 3);
    Rational a = r1 + 4; // 2/3 + 4/1 = 14/3
    Rational b = 4 + r1; // Symmetric: 4/1 + 2/3 = 14/3
    std::cout << a.getNumerator() << "/" << a.getDenominator() << "\n";
    std::cout << b.getNumerator() << "/" << b.getDenominator() << "\n";
    return 0;
}

#include <iostream>

class Coordinate {
private:
    int values[2]; // 0: x, 1: y
public:
    Coordinate(int x = 0, int y = 0) {
        values[0] = x;
        values[1] = y;
    }

    // Subscript operator returning reference for lvalue modification
    int& operator[](int index) {
        return values[index];
    }

    // Augmented assignment returning reference
    Coordinate& operator+=(const Coordinate& other) {
        values[0] += other.values[0];
        values[1] += other.values[1];
        return *this;
    }
};

int main() {
    Coordinate p(10, 20);
    p[0] = 30; // Using subscript result as lvalue
    Coordinate delta(5, 5);
    (p += delta) += delta; // Chained lvalue operation
    std::cout << "x: " << p[0] << ", y: " << p[1] << "\n";
    return 0;
}

#include <iostream>
#include <cstdlib>
#include <numeric>

class Rational {
private:
    int numerator;
    int denominator;

    static int gcd(int n, int d) {
        int n1 = std::abs(n);
        int n2 = std::abs(d);
        int gcdVal = 1;
        for (int k = 1; k <= n1 && k <= n2; k++) {
            if (n1 % k == 0 && n2 % k == 0) gcdVal = k;
        }
        return gcdVal;
    }

public:
    Rational() : numerator(0), denominator(1) {}
    Rational(int n) : numerator(n), denominator(1) {}
    Rational(int n, int d) {
        int factor = gcd(n, d);
        numerator = (d > 0 ? 1 : -1) * n / factor;
        denominator = std::abs(d) / factor;
    }

    int getNumerator() const { return numerator; }
    int getDenominator() const { return denominator; }

    Rational add(const Rational& r) const {
        int n = numerator * r.denominator + denominator * r.numerator;
        int d = denominator * r.denominator;
        return Rational(n, d);
    }

    Rational subtract(const Rational& r) const {
        int n = numerator * r.denominator - denominator * r.numerator;
        int d = denominator * r.denominator;
        return Rational(n, d);
    }

    int compareTo(const Rational& r) const {
        Rational temp = subtract(r);
        if (temp.getNumerator() < 0) return -1;
        if (temp.getNumerator() == 0) return 0;
        return 1;
    }
};

Rational operator+(const Rational& r1, const Rational& r2) { return r1.add(r2); }
bool operator<(const Rational& r1, const Rational& r2) { return r1.compareTo(r2) < 0; }
bool operator==(const Rational& r1, const Rational& r2) { return r1.compareTo(r2) == 0; }

int main() {
    Rational r1(1, 2);
    Rational r2(2, 4); // Reduces to 1/2
    Rational r3(3, 4);

    std::cout << std::boolalpha;
    std::cout << "r1 == r2: " << (r1 == r2) << "\n";
    std::cout << "r1 < r3: " << (r1 < r3) << "\n";
    Rational r4 = r1 + 1; // 1/2 + 1 = 3/2
    std::cout << "r1 + 1: " << r4.getNumerator() << "/" << r4.getDenominator() << "\n";
    return 0;
}
